// The macro implementations live in `MacrosDefinitions`, which cannot import this module. Hence they mirror these cases by name (see `memberwiseInitializable.AccessControl`), keep both in sync.

/// The access control of the declarations generated by a macro.
///
/// Pass one to a macro to control how visible its generated declarations are, eg, ``memberwiseInitializable(_:)``.
public enum AccessControl: BitwiseCopyable, Sendable, Hashable {
    /// Visible to any module that imports the declaring module.
    case `public`
    /// Visible within the declaring module, which is the default access control of Swift.
    case `internal`
    /// Visible only within the enclosing declaration, and its extensions in the same file.
    case `private`
}
